import test from 'node:test';import assert from 'node:assert/strict';import {openSpaces,openSpaceObjects,openSpacePortals,spaceCamera,normalizeOpenProgress,clearOpenGround,openSpaceSvg} from '../src/open-spaces.js';import {pathfind,cellAt,blocked} from '../src/navigation.js';import {zoneExit} from '../src/zones.js';import {objects,materials} from '../src/data.js';import {getJournalEntries} from '../src/journal.js';
test('three large landscapes and hub portals connect every landmark with valid approaches',()=>{assert.equal(Object.keys(openSpaces).filter(id=>!openSpaces[id].chapter&&id!=='magnetism').length,3);for(const [id,z]of Object.entries(openSpaces).filter(([id])=>!openSpaces[id].chapter&&id!=='magnetism')){assert.ok(z.width>1000&&z.height>600);assert.ok(openSpaceSvg(id).includes('<svg'));assert.equal(zoneExit(id,'grounds'),id+'-exit');const portal=openSpacePortals.find(p=>p.to===id);assert.equal(zoneExit('grounds',id),portal.id);assert.ok(pathfind([200,500],[portal.x-65,portal.y+55]).length);for(const o of openSpaceObjects.filter(o=>o.zone===id)){const path=pathfind(z.spawn,[o.x-65,o.y+55],id);assert.ok(path.length,o.id);for(const point of path)assert.equal(blocked(...cellAt(...point,id),id),false);}}});
test('camera follows distant world positions and forest crossing avoids the stream',()=>{assert.deepEqual(spaceCamera('flight',[2100,900]),[1400,600]);assert.deepEqual(spaceCamera('forest',[0,0]),[0,0]);const p=pathfind([180,400],[1900,700],'forest');assert.ok(p.some(([x,y])=>x>=1040&&x<1160&&y>=560&&y<680));assert.ok(cellAt(2100,1350,'diglands')[0]>24)});
test('excavated routes save without duplicates or invalid cells and new visits have journal entries',()=>{const s=normalizeOpenProgress();clearOpenGround(s,500,350);clearOpenGround(s,500,350);assert.equal(s.cleared.length,1);assert.deepEqual(normalizeOpenProgress({cleared:['bad','999,999',...s.cleared]}),s);const visited=new Set(openSpaceObjects.map(o=>o.id));assert.ok(getJournalEntries('did',new Set(),visited,objects,materials).some(e=>e.id==='forest-oak'));});
